import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function AIPlanner() {
  const navigate = useNavigate();
  const [messages, setMessages] = useState([
    { text: 'Halo Andi! Saya WORKIE AI. Deskripsikan pekerjaan yang kamu butuhkan dengan bahasa santai saja. Nanti saya rapikan jadi draf order siap pakai!', sender: 'ai' },
    { text: 'Gue butuh desainer buat bikin logo cafe kopi baru punya temen. Cafe-nya berkonsep minimalis modern.', sender: 'user' },
    { text: 'Siap, logo cafe kopi minimalis modern! Biar rancangannya mantap, boleh tahu detail ini?\n1. Kapan deadlinenya?\n2. Anggarannya berapa?\n3. Desainnya digarap Solo atau Team?', sender: 'ai' },
    { text: 'Butuh kelar 2 hari lagi sih, budget kisaran 250rb-300rb, cukup kerjain Solo aja.', sender: 'user' }
  ]);
  const [input, setInput] = useState('');

  const sendMessage = () => {
    if (!input.trim()) return;
    setMessages([...messages, { text: input, sender: 'user' }]);
    setInput('');
    setTimeout(() => {
      setMessages(prev => [...prev, { text: 'Siap, saya sudah catat semua detailnya! Klik "Lanjutkan" untuk lihat draf order.', sender: 'ai' }]);
    }, 1000);
  };

  return (
    <div style={{ maxWidth: '402px', margin: '0 auto', background: '#F8F9FA', minHeight: '100vh', padding: '16px 20px 80px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '16px' }}>
        <span style={{ fontSize: '24px', cursor: 'pointer' }} onClick={() => navigate('/dashboard-customer')}>←</span>
        <h1 style={{ fontSize: '20px', fontWeight: 800, color: '#0D9488' }}>WORKIE AI Planner</h1>
        <span>🟢</span>
      </div>
      <p style={{ color: '#475569', marginBottom: '16px' }}>Online & Siap Membantu</p>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginBottom: '16px' }}>
        {messages.map((msg, i) => (
          <div key={i} style={{ maxWidth: '85%', alignSelf: msg.sender === 'ai' ? 'flex-start' : 'flex-end' }}>
            <div style={{ padding: '12px 16px', borderRadius: '16px', background: msg.sender === 'ai' ? 'white' : '#0D9488', color: msg.sender === 'ai' ? '#0F172A' : 'white' }}>
              {msg.text.split('\n').map((line, j) => <div key={j}>{line}</div>)}
            </div>
            <p style={{ fontSize: '11px', color: '#94A3B8', marginTop: '4px' }}>{msg.sender === 'ai' ? 'WORKIE AI' : 'Andi'}</p>
          </div>
        ))}
      </div>

      <div style={{ display: 'flex', gap: '8px', position: 'fixed', bottom: '80px', left: '50%', transform: 'translateX(-50%)', maxWidth: '402px', width: '90%', background: 'white', padding: '8px', borderRadius: '12px', border: '1px solid #E2E8F0' }}>
        <input type="text" placeholder="Ketik balasan Anda disini..." value={input} onChange={(e) => setInput(e.target.value)} onKeyPress={(e) => e.key === 'Enter' && sendMessage()} style={{ flex: 1, padding: '10px', border: 'none', outline: 'none', fontSize: '14px' }} />
        <button onClick={sendMessage} style={{ padding: '8px 16px', background: '#0D9488', color: 'white', border: 'none', borderRadius: '8px' }}>➤</button>
      </div>

      <button onClick={() => navigate('/order-detail')} style={{ width: '100%', padding: '14px', background: '#0D9488', color: 'white', border: 'none', borderRadius: '12px', fontSize: '16px', fontWeight: 700, marginTop: '16px' }}>Lanjutkan ke Order Detail</button>
    </div>
  );
}

export default AIPlanner;
